function debounce(fn, wait) {
  let timeoutId = null;
  function debounced(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), wait);
  }
  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = null;
  };
  return debounced;
}

const onSearch = debounce((q) => fetch('/api?q=' + q), 300);

function throttle(fn, wait) {
  let last = 0;
  let timeoutId = null;
  return function throttled(...args) {
    const now = Date.now();
    const remaining = wait - (now - last);
    if (remaining <= 0) {
      last = now;
      fn.apply(this, args);
    } else if (!timeoutId) {
      timeoutId = setTimeout(() => {
        last = Date.now();
        timeoutId = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

useEffect(() => {
  const onResize = debounce(() => setWidth(window.innerWidth), 150);
  window.addEventListener('resize', onResize);
  return () => {
    onResize.cancel?.();
    window.removeEventListener('resize', onResize);
  };
}, []);

function debounceLeading(fn, wait) {
  let timeoutId = null;
  return function (...args) {
    if (!timeoutId) fn.apply(this, args);
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => { timeoutId = null; }, wait);
  };
}

function rafThrottle(fn) {
  let ticking = false;
  return function (...args) {
    if (!ticking) {
      requestAnimationFrame(() => {
        fn.apply(this, args);
        ticking = false;
      });
      ticking = true;
    }
  };
}
